// (generated by gen_module_docs.py: the module's docstring ("") and its classes', methods' and functions' (by name))

#pragma once

#include <cstring>

namespace neos::python_runtime::detail::logging_handlers_docs
{
    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "\nAdditional handlers for the logging package for Python. The core package is\nbased on PEP 282 and comments thereto in comp.lang.python.\n\nCopyright (C) 2001-2021 Vinay Sajip. All Rights Reserved.\n\nTo use, simply 'import logging.handlers' and log away!\n" },
        { "BaseRotatingHandler", "\nBase class for handlers that rotate log files at a certain point.\nNot meant to be instantiated directly.  Instead, use RotatingFileHandler\nor TimedRotatingFileHandler.\n" },
        { "BaseRotatingHandler.__init__", "\nUse the specified filename for streamed logging\n" },
        { "BaseRotatingHandler.emit", "\nEmit a record.\n\nOutput the record to the file, catering for rollover as described\nin doRollover().\n" },
        { "BaseRotatingHandler.rotation_filename", "\nModify the filename of a log file when rotating.\n\nThis is provided so that a custom filename can be provided.\n\nThe default implementation calls the 'namer' attribute of the\nhandler, if it's callable, passing the default name to\nit. If the attribute isn't callable (the default is None), the name\nis returned unchanged.\n\n:param default_name: The default name for the log file.\n" },
        { "BaseRotatingHandler.rotate", "\nWhen rotating, rotate the current log.\n\nThe default implementation calls the 'rotator' attribute of the\nhandler, if it's callable, passing the source and dest arguments to\nit. If the attribute isn't callable (the default is None), the source\nis simply renamed to the destination.\n\n:param source: The source filename. This is normally the base\n               filename, e.g. 'test.log'\n:param dest:   The destination filename. This is normally\n               what the source is rotated to, e.g. 'test.log.1'.\n" },
        { "BufferingHandler", "\nA handler class which buffers logging records in memory. Whenever each\nrecord is added to the buffer, a check is made to see if the buffer should\nbe flushed. If it should, then flush() is expected to do what's needed.\n  " },
        { "BufferingHandler.__init__", "\nInitialize the handler with the buffer size.\n" },
        { "BufferingHandler.shouldFlush", "\nShould the handler flush its buffer?\n\nReturns true if the buffer is up to capacity. This method can be\noverridden to implement custom flushing strategies.\n" },
        { "BufferingHandler.emit", "\nEmit a record.\n\nAppend the record. If shouldFlush() tells us to, call flush() to process\nthe buffer.\n" },
        { "BufferingHandler.flush", "\nOverride to implement custom flushing behaviour.\n\nThis version just zaps the buffer to empty.\n" },
        { "BufferingHandler.close", "\nClose the handler.\n\nThis version just flushes and chains to the parent class' close().\n" },
        { "DatagramHandler", "\nA handler class which writes logging records, in pickle format, to\na datagram socket.  The pickle which is sent is that of the LogRecord's\nattribute dictionary (__dict__), so that the receiver does not need to\nhave the logging module installed in order to process the logging event.\n\nTo unpickle the record at the receiving end into a LogRecord, use the\nmakeLogRecord function.\n\n" },
        { "DatagramHandler.__init__", "\nInitializes the handler with a specific host address and port.\n" },
        { "DatagramHandler.makeSocket", "\nThe factory method of SocketHandler is here overridden to create\na UDP socket (SOCK_DGRAM).\n" },
        { "DatagramHandler.send", "\nSend a pickled string to a socket.\n\nThis function no longer allows for partial sends which can happen\nwhen the network is busy - UDP does not guarantee delivery and\ncan deliver packets out of sequence.\n" },
        { "HTTPHandler", "\nA class which sends records to a web server, using either GET or\nPOST semantics.\n" },
        { "HTTPHandler.__init__", "\nInitialize the instance with the host, the request URL, and the method\n(\"GET\" or \"POST\")\n" },
        { "HTTPHandler.mapLogRecord", "\nDefault implementation of mapping the log record into a dict\nthat is sent as the CGI data. Overwrite in your class.\nContributed by Franz Glasner.\n" },
        { "HTTPHandler.getConnection", "\nget a HTTP[S]Connection.\n\nOverride when a custom connection is required, for example if\nthere is a proxy.\n" },
        { "HTTPHandler.emit", "\nEmit a record.\n\nSend the record to the web server as a percent-encoded dictionary\n" },
        { "MemoryHandler", "\nA handler class which buffers logging records in memory, periodically\nflushing them to a target handler. Flushing occurs whenever the buffer\nis full, or when an event of a certain severity or greater is seen.\n" },
        { "MemoryHandler.__init__", "\nInitialize the handler with the buffer size, the level at which\nflushing should occur and an optional target.\n\nNote that without a target being set either here or via setTarget(),\na MemoryHandler is no use to anyone!\n\nThe ``flushOnClose`` argument is ``True`` for backward compatibility\nreasons - the old behaviour is that when the handler is closed, the\nbuffer is flushed, even if the flush level hasn't been exceeded nor the\ncapacity exceeded. To prevent this, set ``flushOnClose`` to ``False``.\n" },
        { "MemoryHandler.shouldFlush", "\nCheck for buffer full or a record at the flushLevel or higher.\n" },
        { "MemoryHandler.setTarget", "\nSet the target handler for this handler.\n" },
        { "MemoryHandler.flush", "\nFor a MemoryHandler, flushing means just sending the buffered\nrecords to the target, if there is one. Override if you want\ndifferent behaviour.\n\nThe record buffer is only cleared if a target has been set.\n" },
        { "MemoryHandler.close", "\nFlush, if appropriately configured, set the target to None and lose the\nbuffer.\n" },
        { "NTEventLogHandler", "\nA handler class which sends events to the NT Event Log. Adds a\nregistry entry for the specified application name. If no dllname is\nprovided, win32service.pyd (which contains some basic message\nplaceholders) is used. Note that use of these placeholders will make\nyour event logs big, as the entire message source is held in the log.\nIf you want slimmer logs, you have to pass in the name of your own DLL\nwhich contains the message definitions you want to use in the event log.\n" },
        { "NTEventLogHandler.getMessageID", "\nReturn the message ID for the event record. If you are using your\nown messages, you could do this by having the msg passed to the\nlogger being an ID rather than a formatting string. Then, in here,\nyou could use a dictionary lookup to get the message ID. This\nversion returns 1, which is the base message ID in win32service.pyd.\n" },
        { "NTEventLogHandler.getEventCategory", "\nReturn the event category for the record.\n\nOverride this if you want to specify your own categories. This version\nreturns 0.\n" },
        { "NTEventLogHandler.getEventType", "\nReturn the event type for the record.\n\nOverride this if you want to specify your own types. This version does\na mapping using the handler's typemap attribute, which is set up in\n__init__() to a dictionary which contains mappings for DEBUG, INFO,\nWARNING, ERROR and CRITICAL. If you are using your own levels you will\neither need to override this method or place a suitable dictionary in\nthe handler's typemap attribute.\n" },
        { "NTEventLogHandler.emit", "\nEmit a record.\n\nDetermine the message ID, event category and event type. Then\nlog the message in the NT event log.\n" },
        { "NTEventLogHandler.close", "\nClean up this handler.\n\nYou can remove the application name from the registry as a\nsource of event log entries. However, if you do this, you will\nnot be able to see the events as you intended in the Event Log\nViewer - it needs to be able to access the registry to get the\nDLL name.\n" },
        { "QueueHandler", "\nThis handler sends events to a queue. Typically, it would be used together\nwith a multiprocessing Queue to centralise logging to file in one process\n(in a multi-process application), so as to avoid file write contention\nbetween processes.\n\nThis code is new in Python 3.2, but this class can be copy pasted into\nuser code for use with earlier Python versions.\n" },
        { "QueueHandler.__init__", "\nInitialise an instance, using the passed queue.\n" },
        { "QueueHandler.enqueue", "\nEnqueue a record.\n\nThe base implementation uses put_nowait. You may want to override\nthis method if you want to use blocking, timeouts or custom queue\nimplementations.\n" },
        { "QueueHandler.prepare", "\nPrepare a record for queuing. The object returned by this method is\nenqueued.\n\nThe base implementation formats the record to merge the message and\narguments, and removes unpickleable items from the record in-place.\nSpecifically, it overwrites the record's `msg` and\n`message` attributes with the merged message (obtained by\ncalling the handler's `format` method), and sets the `args`,\n`exc_info` and `exc_text` attributes to None.\n\nYou might want to override this method if you want to convert\nthe record to a dict or JSON string, or send a modified copy\nof the record while leaving the original intact.\n" },
        { "QueueHandler.emit", "\nEmit a record.\n\nWrites the LogRecord to the queue, preparing it for pickling first.\n" },
        { "QueueListener", "\nThis class implements an internal threaded listener which watches for\nLogRecords being added to a queue, removes them and passes them to a\nlist of handlers for processing.\n" },
        { "QueueListener.__init__", "\nInitialise an instance with the specified queue and\nhandlers.\n" },
        { "QueueListener.dequeue", "\nDequeue a record and return it, optionally blocking.\n\nThe base implementation uses get. You may want to override this method\nif you want to use timeouts or work with custom queue implementations.\n" },
        { "QueueListener.start", "\nStart the listener.\n\nThis starts up a background thread to monitor the queue for\nLogRecords to process.\n" },
        { "QueueListener.prepare", "\nPrepare a record for handling.\n\nThis method just returns the passed-in record. You may want to\noverride this method if you need to do any custom marshalling or\nmanipulation of the record before passing it to the handlers.\n" },
        { "QueueListener.handle", "\nHandle a record.\n\nThis just loops through the handlers offering them the record\nto handle.\n" },
        { "QueueListener._monitor", "\nMonitor the queue for records, and ask the handler\nto deal with them.\n\nThis method runs on a separate, internal thread.\nThe thread will terminate if it sees a sentinel object in the queue.\n" },
        { "QueueListener.enqueue_sentinel", "\nThis is used to enqueue the sentinel record.\n\nThe base implementation uses put_nowait. You may want to override this\nmethod if you want to use timeouts or work with custom queue\nimplementations.\n" },
        { "QueueListener.stop", "\nStop the listener.\n\nThis asks the thread to terminate, and then waits for it to do so.\nNote that if you don't call this before your application exits, there\nmay be some records still left on the queue, which won't be processed.\n" },
        { "RotatingFileHandler", "\nHandler for logging to a set of files, which switches from one file\nto the next when the current file reaches a certain size.\n" },
        { "RotatingFileHandler.__init__", "\nOpen the specified file and use it as the stream for logging.\n\nBy default, the file grows indefinitely. You can specify particular\nvalues of maxBytes and backupCount to allow the file to rollover at\na predetermined size.\n\nRollover occurs whenever the current log file is nearly maxBytes in\nlength. If backupCount is >= 1, the system will successively create\nnew files with the same pathname as the base file, but with extensions\n\".1\", \".2\" etc. appended to it. For example, with a backupCount of 5\nand a base file name of \"app.log\", you would get \"app.log\",\n\"app.log.1\", \"app.log.2\", ... through to \"app.log.5\". The file being\nwritten to is always \"app.log\" - when it gets filled up, it is closed\nand renamed to \"app.log.1\", and if files \"app.log.1\", \"app.log.2\" etc.\nexist, then they are renamed to \"app.log.2\", \"app.log.3\" etc.\nrespectively.\n\nIf maxBytes is zero, rollover never occurs.\n" },
        { "RotatingFileHandler.doRollover", "\nDo a rollover, as described in __init__().\n" },
        { "RotatingFileHandler.shouldRollover", "\nDetermine if rollover should occur.\n\nBasically, see if the supplied record would cause the file to exceed\nthe size limit we have.\n" },
        { "SMTPHandler", "\nA handler class which sends an SMTP email for each logging event.\n" },
        { "SMTPHandler.__init__", "\nInitialize the handler.\n\nInitialize the instance with the from and to addresses and subject\nline of the email. To specify a non-standard SMTP port, use the\n(host, port) tuple format for the mailhost argument. To specify\nauthentication credentials, supply a (username, password) tuple\nfor the credentials argument. To specify the use of a secure\nprotocol (TLS), pass in a tuple for the secure argument. This will\nonly be used when authentication credentials are supplied. The tuple\nwill be either an empty tuple, or a single-value tuple with the name\nof a keyfile, or a 2-value tuple with the names of the keyfile and\ncertificate file. (This tuple is passed to the\n`ssl.SSLContext.load_cert_chain` method).\nA timeout in seconds can be specified for the SMTP connection (the\ndefault is one second).\n" },
        { "SMTPHandler.getSubject", "\nDetermine the subject for the email.\n\nIf you want to specify a subject line which is record-dependent,\noverride this method.\n" },
        { "SMTPHandler.emit", "\nEmit a record.\n\nFormat the record and send it to the specified addressees.\n" },
        { "SocketHandler", "\nA handler class which writes logging records, in pickle format, to\na streaming socket. The socket is kept open across logging calls.\nIf the peer resets it, an attempt is made to reconnect on the next call.\nThe pickle which is sent is that of the LogRecord's attribute dictionary\n(__dict__), so that the receiver does not need to have the logging module\ninstalled in order to process the logging event.\n\nTo unpickle the record at the receiving end into a LogRecord, use the\nmakeLogRecord function.\n" },
        { "SocketHandler.__init__", "\nInitializes the handler with a specific host address and port.\n\nWhen the attribute *closeOnError* is set to True - if a socket error\noccurs, the socket is silently closed and then reopened on the next\nlogging call.\n" },
        { "SocketHandler.makeSocket", "\nA factory method which allows subclasses to define the precise\ntype of socket they want.\n" },
        { "SocketHandler.createSocket", "\nTry to create a socket, using an exponential backoff with\na max retry time. Thanks to Robert Olson for the original patch\n(SF #815911) which has been slightly refactored.\n" },
        { "SocketHandler.send", "\nSend a pickled string to the socket.\n\nThis function allows for partial sends which can happen when the\nnetwork is busy.\n" },
        { "SocketHandler.makePickle", "\nPickles the record in binary format with a length prefix, and\nreturns it ready for transmission across the socket.\n" },
        { "SocketHandler.handleError", "\nHandle an error during logging.\n\nAn error has occurred during logging. Most likely cause -\nconnection lost. Close the socket so that we can retry on the\nnext event.\n" },
        { "SocketHandler.emit", "\nEmit a record.\n\nPickles the record and writes it to the socket in binary format.\nIf there is an error with the socket, silently drop the packet.\nIf there was a problem with the socket, re-establishes the\nsocket.\n" },
        { "SocketHandler.close", "\nCloses the socket.\n" },
        { "SysLogHandler", "\nA handler class which sends formatted logging records to a syslog\nserver. Based on Sam Rushing's syslog module:\nhttp://www.nightmare.com/squirl/python-ext/misc/syslog.py\nContributed by Nicolas Untz (after which minor refactoring changes\nhave been made).\n" },
        { "SysLogHandler.__init__", "\nInitialize a handler.\n\nIf address is specified as a string, a UNIX socket is used. To log to a\nlocal syslogd, \"SysLogHandler(address=\"/dev/log\")\" can be used.\nIf facility is not specified, LOG_USER is used. If socktype is\nspecified as socket.SOCK_DGRAM or socket.SOCK_STREAM, that specific\nsocket type will be used. For Unix sockets, you can also specify a\nsocktype of None, in which case socket.SOCK_DGRAM will be used, falling\nback to socket.SOCK_STREAM.\n" },
        { "SysLogHandler.createSocket", "\nTry to create a socket and, if it's not a datagram socket, connect it\nto the other end. This method is called during handler initialization,\nbut it's not regarded as an error if the other end isn't listening yet\n--- the method will be called again when emitting an event,\nif there is no socket at that point.\n" },
        { "SysLogHandler.encodePriority", "\nEncode the facility and priority. You can pass in strings or\nintegers - if strings are passed, the facility_names and\npriority_names mapping dictionaries are used to convert them to\nintegers.\n" },
        { "SysLogHandler.close", "\nCloses the socket.\n" },
        { "SysLogHandler.mapPriority", "\nMap a logging level name to a key in the priority_names map.\nThis is useful in two scenarios: when custom levels are being\nused, and in the case where you can't do a straightforward\nmapping by lowercasing the logging level name because of locale-\nspecific issues (see SF #1524081).\n" },
        { "SysLogHandler.emit", "\nEmit a record.\n\nThe record is formatted, and then sent to the syslog server. If\nexception information is present, it is NOT sent to the server.\n" },
        { "TimedRotatingFileHandler", "\nHandler for logging to a file, rotating the log file at certain timed\nintervals.\n\nIf backupCount is > 0, when rollover is done, no more than backupCount\nfiles are kept - the oldest ones are deleted.\n" },
        { "TimedRotatingFileHandler.computeRollover", "\nWork out the rollover time based on the specified time.\n" },
        { "TimedRotatingFileHandler.shouldRollover", "\nDetermine if rollover should occur.\n\nrecord is not used, as we are just comparing times, but it is needed so\nthe method signatures are the same\n" },
        { "TimedRotatingFileHandler.getFilesToDelete", "\nDetermine the files to delete when rolling over.\n\nMore specific than the earlier method, which just used glob.glob().\n" },
        { "TimedRotatingFileHandler.doRollover", "\ndo a rollover; in this case, a date/time stamp is appended to the filename\nwhen the rollover happens.  However, you want the file to be named for the\nstart of the interval, not the current time.  If there is a backup count,\nthen we have to get a list of matching filenames, sort them and remove\nthe one with the oldest suffix.\n" },
        { "WatchedFileHandler", "\nA handler for logging to a file, which watches the file\nto see if it has changed while in use. This can happen because of\nusage of programs such as newsyslog and logrotate which perform\nlog file rotation. This handler, intended for use under Unix,\nwatches the file to see if it has changed since the last emit.\n(A file has changed if its device or inode have changed.)\nIf it has changed, the old file stream is closed, and the file\nopened to get a new stream.\n\nThis handler is not appropriate for use under Windows, because\nunder Windows open files cannot be moved or renamed - logging\nopens the files with exclusive locks - and so there is no need\nfor such a handler.\n\nThis handler is based on a suggestion and patch by Chad J.\nSchroeder.\n" },
        { "WatchedFileHandler.reopenIfNeeded", "\nReopen log file if needed.\n\nChecks if the underlying file has changed, and if it\nhas, close the old stream and reopen the file to get the\ncurrent stream.\n" },
        { "WatchedFileHandler.emit", "\nEmit a record.\n\nIf underlying file has changed, reopen the file before emitting the\nrecord to it.\n" },
    };
    inline char const* doc(char const* aName)
    {
        for (auto const& e : sDocs)
            if (std::strcmp(e.name, aName) == 0)
                return e.doc;
        return nullptr;
    }
}
